    const SUPPORTED_LANGS=['cs','en','de','es','fr'];
    const savedLang=localStorage.getItem('siteLang');
    const browserLang=(navigator.language||'en').slice(0,2).toLowerCase();
    let lang=SUPPORTED_LANGS.includes(savedLang)?savedLang:(SUPPORTED_LANGS.includes(browserLang)?browserLang:'en');
    let theme=localStorage.getItem('siteTheme')||((window.matchMedia&&matchMedia('(prefers-color-scheme: light)').matches)?'light':'dark');
    let layout=localStorage.getItem('siteLayout')||'grid';
    let communityPage=0;
    let communityCategory=localStorage.getItem('scriptable-community-category')||'all';
    let communityAvailability=localStorage.getItem('scriptable-community-availability')||'all';
    let communitySort=localStorage.getItem('scriptable-community-sort')||'name';
    let communitySearch=localStorage.getItem('scriptable-community-query')||'';
    const COMMUNITY_AVAILABILITY=new Set(['all','online','offline']);
    const COMMUNITY_SORTS=new Set(['name','author']);
    const CATEGORY_ORDER=['all','sport','weather','news','calendar','finance','space','tools','reading','cars','gaming','music','social','mobile','health','travel','art','shopping'];
    const CATEGORY_LABELS={all:{cs:'Vše',en:'All'},sport:{cs:'Sport',en:'Sport'},weather:{cs:'Počasí',en:'Weather'},news:{cs:'Zprávy',en:'News'},calendar:{cs:'Kalendář',en:'Calendar'},finance:{cs:'Finance',en:'Finance'},space:{cs:'Vesmír',en:'Space'},tools:{cs:'Nástroje',en:'Tools'},reading:{cs:'Čtení',en:'Reading'},cars:{cs:'Auta',en:'Cars'},gaming:{cs:'Hry',en:'Gaming'},music:{cs:'Hudba',en:'Music'},social:{cs:'Sociální',en:'Social'},mobile:{cs:'Mobil',en:'Mobile'},health:{cs:'Zdraví',en:'Health'},travel:{cs:'Cestování',en:'Travel'},art:{cs:'Design',en:'Design'},shopping:{cs:'Nakupování',en:'Shopping'}};
    const uiText=(cs,en)=>window.ScriptableI18n?.translate(cs,en,lang)||(lang==='cs'?cs:en);
    const tr=(cs,en)=>uiText(cs,en);
    const appTr=(cs,en)=>lang==='cs'?cs:en;
    const escapeAttr=value=>String(value??'').replace(/&/g,'&amp;').replace(/\"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

    function applyTheme(next){theme=next==='light'?'light':'dark';localStorage.setItem('siteTheme',theme);document.documentElement.dataset.theme=theme;document.getElementById('themeDark').classList.toggle('active',theme==='dark');document.getElementById('themeLight').classList.toggle('active',theme==='light');document.getElementById('themeColor').content=theme==='dark'?'#070b14':'#eef3f8'}
    function applyLayout(next){layout=next==='list'?'list':'grid';localStorage.setItem('siteLayout',layout);document.body.classList.toggle('layout-list',layout==='list');document.getElementById('layoutGrid').classList.toggle('active',layout==='grid');document.getElementById('layoutList').classList.toggle('active',layout==='list')}
    function setLanguage(next){lang=SUPPORTED_LANGS.includes(next)?next:'en';localStorage.setItem('siteLang',lang);document.documentElement.lang=lang;document.querySelectorAll('[data-cs]').forEach(el=>{el.textContent=el.getAttribute('data-'+lang)||uiText(el.getAttribute('data-cs'),el.getAttribute('data-en'))||el.textContent});const search=document.getElementById('communitySearch');if(search)search.placeholder=search.getAttribute('data-placeholder-'+lang)||uiText(search.getAttribute('data-placeholder-cs'),search.getAttribute('data-placeholder-en'))||'';document.querySelectorAll('[data-language]').forEach(btn=>btn.classList.toggle('active',btn.dataset.language===lang));const settings=document.getElementById('settingsBtn');if(settings){const label=uiText('Nastavení','Settings');settings.title=label;settings.setAttribute('aria-label',label)}const grid=document.getElementById('layoutGrid');if(grid)grid.title=uiText('Mřížka','Grid');const list=document.getElementById('layoutList');if(list)list.title=uiText('Seznam','List');const close=document.querySelector('[data-support-close]');if(close)close.setAttribute('aria-label',uiText('Zavřít','Close'));const nav=document.querySelector('nav.nav');if(nav)nav.setAttribute('aria-label',uiText('Hlavní navigace','Primary'));renderAll()}

    async function copyCode(file,id){const status=document.getElementById(id);status.textContent=tr('Kopíruji…','Copying…');try{const response=await fetch(file,{cache:'no-store'});if(!response.ok)throw new Error('HTTP '+response.status);await navigator.clipboard.writeText(await response.text());status.textContent=tr('✓ Kód zkopírován','✓ Code copied')}catch(_){status.textContent=tr('⚠️ Kopírování selhalo','⚠️ Copy failed')}}
    async function installRemote(file,filename,name,id){const status=document.getElementById(id);status.textContent=tr('Připravuji instalaci…','Preparing installation…');try{if(/\.scriptable(?:$|\?)/i.test(filename||file)){const a=document.createElement('a');a.href=file;a.download=filename||'script.scriptable';document.body.appendChild(a);a.click();a.remove();status.textContent=tr('✓ Otevírám v Scriptable','✓ Opening in Scriptable');return}const response=await fetch(file,{cache:'no-store'});if(!response.ok)throw new Error('HTTP '+response.status);const code=await response.text();if(!code.trim())throw new Error('Empty script');const originalName=((filename||name||'Script').replace(/\.js$/i,'').trim()||'Script');const color=((code.match(/^\s*\/\/\s*icon-color:\s*([^;\r\n]+);/mi)||[])[1]||'deep-blue').trim();const glyph=((code.match(/^\s*\/\/\s*icon-glyph:\s*([^;\r\n]+);/mi)||[])[1]||'code').trim();const pkg={always_run_in_app:false,icon:{color,glyph},name:originalName,script:code,share_sheet_inputs:[]};const blob=new Blob([JSON.stringify(pkg,null,2)],{type:'application/octet-stream'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=originalName.replace(/[\\/:*?"<>|]/g,'-')+'.scriptable';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2500);status.textContent=tr('✓ Připraveno pro Scriptable','✓ Ready for Scriptable')}catch(_){status.textContent=tr('⚠️ Instalace selhala – otevírám originál','⚠️ Install failed – opening original');window.open(file,'_blank','noopener')}}

    function isGenericCommunityFeatures(items){if(!Array.isArray(items)||items.length!==3)return false;const joined=items.join('|').toLowerCase();return joined.includes('open-source projekt')||joined.includes('open-source project')||joined.includes('komunitní projekt')||joined.includes('community project')||joined.includes('stahování přímo od autora')||joined.includes('direct download from the author')}
    function researchedFeatures(app,rawFeatures){const details=FEATURE_DETAILS[app.name];if(details)return details.map(pair=>pair[lang==='cs'?0:1]);if(!isGenericCommunityFeatures(rawFeatures))return rawFeatures;const desc=(app.description&&app.description[lang]?app.description[lang]:'').replace(/[.!?]+$/,'');const tagLine=(app.tags||[]).slice(0,3).join(' · ');return [desc,tagLine?appTr(`Zaměření: ${tagLine}`,`Focus: ${tagLine}`):appTr('Scriptable widget','Scriptable widget'),appTr(`Původní projekt autora ${app.author}`,`Original project by ${app.author}`)]}
    function cardHtml(app,index,external){const rawFeatures=(app.features&&app.features[lang])||app.features?.en||app.features?.cs||[];const visibleFeatures=external?researchedFeatures(app,rawFeatures):rawFeatures;const features=visibleFeatures.length?`<ul class="features">${visibleFeatures.map(x=>`<li title="${escapeAttr(x)}">${x}</li>`).join('')}</ul>`:'';const tags=app.tags.map(x=>`<span class="tag">${x}</span>`).join('');const statusId=(external?'externalStatus':'ourStatus')+index;const imgClass=external?'':' ourPreview';const badge=external?`<div class="externalBadge">${tr('Jiný vývojář','Third-party')}</div>`:`<div class="version">v${app.version}</div>`;const author=external?`<div class="authorStatusRow"><div class="author">${tr('Autor','Author')}: ${app.author}</div>`:'';const availability=external?communityStatusBadge(app)+`</div>`:'';let actions='';let actionClass=external?'':'ourActions';if(external){if(Array.isArray(app.variants)&&app.variants.length){actionClass='variantActions';const variantButtons=app.variants.map(v=>`<button class="btn primary" type="button" data-install-remote data-file="${escapeAttr(v.file)}" data-filename="${escapeAttr(v.filename||app.filename)}" data-name="${escapeAttr(app.name+' · '+(v.label||''))}" data-status-id="${escapeAttr(statusId)}">📲 ${v.label||tr('Varianta','Variant')}</button>`).join('');actions=`${variantButtons}<a class="btn secondary variantProject" href="${app.source}" target="_blank" rel="noopener">${tr('↗ Projekt','↗ Project')}</a>`}else{actions=`<button class="btn primary" type="button" data-install-remote data-file="${escapeAttr(app.file)}" data-filename="${escapeAttr(app.filename)}" data-name="${escapeAttr(app.name)}" data-status-id="${escapeAttr(statusId)}">${tr('📲 Instalovat','📲 Install')}</button><a class="btn secondary" href="${app.source}" target="_blank" rel="noopener">${tr('↗ Projekt','↗ Project')}</a>`}}else{actions=`<a class="btn primary" href="${app.install}" download>${tr('📲 Instalovat','📲 Install')}</a>`}return `<article class="card"><div class="preview${imgClass}"><img src="${app.preview}" alt="${escapeAttr(app.name)} preview" loading="lazy">${badge}</div><div class="body"><div class="titleRow"><div class="appIcon">${app.icon}</div><div class="appTitle"><h3 title="${escapeAttr(app.name)}">${app.name}</h3><p>${app.description?.[lang]||app.description?.en||app.description?.cs||''}</p>${author}${availability}</div></div><div class="tags">${tags}</div>${features}<div class="actions ${actionClass}">${actions}</div><div id="${statusId}" class="status"></div></div></article>`}

    function categoryLabel(category){const x=CATEGORY_LABELS[category]||{cs:category,en:category};return uiText(x.cs||category,x.en||x.cs||category)}
    function normalizeSearch(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim()}
    function toggleCommunityFilter(currentValue,requestedValue,allowedValues){const next=allowedValues.has(requestedValue)?requestedValue:'all';return next!=='all'&&next===currentValue?'all':next}
    function communityAvailabilityValue(app){const item=communityStatusFor(app);if(item?.online===true)return 'online';if(item?.checkedAt)return 'offline';return 'checking'}
    function compareCommunityApps(left,right){const byName=()=>String(left.name||'').localeCompare(String(right.name||''),lang,{sensitivity:'base'});if(communitySort==='author'){const diff=String(left.author||'').localeCompare(String(right.author||''),lang,{sensitivity:'base'});return diff||byName()}return byName()}
    function filteredCommunityApps(){let rows=communityCategory==='all'?[...communityApps]:communityApps.filter(app=>app.category===communityCategory);if(communityAvailability!=='all')rows=rows.filter(app=>communityAvailabilityValue(app)===communityAvailability);const q=normalizeSearch(communitySearch);if(q)rows=rows.filter(app=>{const haystack=[app.name,app.author,app.category,...(app.tags||[]),app.description?.cs,app.description?.en,...(app.features?.cs||[]),...(app.features?.en||[])].filter(Boolean).join(' ');return normalizeSearch(haystack).includes(q)});return rows.sort(compareCommunityApps)}
    function communityFilterButton(label,value,active,handler){return `<button class="filter ${active?'active':''}" type="button" aria-pressed="${active}" data-community-filter="${handler}" data-filter-value="${escapeAttr(value)}">${label}</button>`}
    function renderCommunityFilters(){if(!CATEGORY_ORDER.includes(communityCategory))communityCategory='all';if(!COMMUNITY_AVAILABILITY.has(communityAvailability))communityAvailability='all';if(!COMMUNITY_SORTS.has(communitySort))communitySort='name';const availabilityHost=document.getElementById('availabilityFilters');if(availabilityHost)availabilityHost.innerHTML=[['all',tr('Vše','All')],['online','Online'],['offline','Offline']].map(([value,label])=>communityFilterButton(label,value,communityAvailability===value,'setAvailabilityFilter')).join('');const categoryHost=document.getElementById('categoryFilters');if(categoryHost){const present=new Set(communityApps.map(app=>app.category));const options=CATEGORY_ORDER.filter(x=>x==='all'||present.has(x));categoryHost.innerHTML=options.map(value=>communityFilterButton(categoryLabel(value),value,communityCategory===value,'setCategory')).join('')}const sortHost=document.getElementById('sortFilters');if(sortHost)sortHost.innerHTML=[['name',tr('Název A–Z','Name A–Z')],['author',tr('Autor A–Z','Author A–Z')]].map(([value,label])=>communityFilterButton(label,value,communitySort===value,'setCommunitySort')).join('');const search=document.getElementById('sourceSearch');if(search){if(search.value!==communitySearch)search.value=communitySearch;search.placeholder=tr('Hledat projekty…','Search projects…')}setupCommunityFilterDisclosure();syncCommunityFilterSummary()}
    function scrollActiveCommunityFilter(id){requestAnimationFrame(()=>document.getElementById(id)?.querySelector('.filter.active')?.scrollIntoView({block:'nearest',inline:'nearest',behavior:'smooth'}))}
    function updateCommunityCount(){const filtered=filteredCommunityApps().length;const active=communityCategory!=='all'||communityAvailability!=='all'||communitySort!=='name'||normalizeSearch(communitySearch);document.getElementById('communityCount').textContent=(active?`${filtered} / ${communityApps.length}`:communityApps.length)+' '+tr('projektů','projects');syncCommunityFilterSummary()}
    function setCategory(category){const requested=CATEGORY_ORDER.includes(category)?category:'all';communityCategory=toggleCommunityFilter(communityCategory,requested,new Set(CATEGORY_ORDER));localStorage.setItem('scriptable-community-category',communityCategory);communityPage=0;renderCommunityFilters();renderCommunity();updateCommunityCount();scrollActiveCommunityFilter('categoryFilters')}
    function setAvailabilityFilter(value){communityAvailability=toggleCommunityFilter(communityAvailability,value,COMMUNITY_AVAILABILITY);localStorage.setItem('scriptable-community-availability',communityAvailability);communityPage=0;renderCommunityFilters();renderCommunity();updateCommunityCount();scrollActiveCommunityFilter('availabilityFilters')}
    function setCommunitySort(value){communitySort=COMMUNITY_SORTS.has(value)?value:'name';localStorage.setItem('scriptable-community-sort',communitySort);communityPage=0;renderCommunityFilters();renderCommunity();updateCommunityCount();scrollActiveCommunityFilter('sortFilters')}
    function setCommunitySearch(value){communitySearch=value||'';localStorage.setItem('scriptable-community-query',communitySearch);communityPage=0;renderCommunity();updateCommunityCount()}
    function clearCommunityFilters(event){event?.preventDefault();event?.stopPropagation();communityCategory='all';communityAvailability='all';communitySort='name';communitySearch='';localStorage.setItem('scriptable-community-category','all');localStorage.setItem('scriptable-community-availability','all');localStorage.setItem('scriptable-community-sort','name');localStorage.setItem('scriptable-community-query','');communityPage=0;renderCommunityFilters();renderCommunity();updateCommunityCount()}
    function setupCommunityFilterDisclosure(){const details=document.querySelector('details.filter-disclosure');if(!details||details.dataset.filterReady)return;details.dataset.filterReady='1';details.addEventListener('toggle',syncCommunityFilterSummary)}
    function syncCommunityFilterSummary(){const details=document.querySelector('details.filter-disclosure');const actions=document.getElementById('communityFilterSummaryActions');const countNode=document.getElementById('communityFilterSummaryCount');const clear=document.querySelector('.filter-summary-clear');if(!details||!actions)return;let count=0;if(communityAvailability!=='all')count++;if(communityCategory!=='all')count++;if(communitySort!=='name')count++;if(normalizeSearch(communitySearch))count++;if(countNode)countNode.textContent=`${count} ${tr('aktivní','active')}`;if(clear){clear.textContent=`${tr('Smazat filtry','Clear filters')} ×`;clear.setAttribute('aria-label',tr('Smazat filtry','Clear filters'))}actions.hidden=details.open||count===0}
    function setCommunityPage(page){const rows=filteredCommunityApps();const pages=Math.max(1,Math.ceil(rows.length/PAGE_SIZE));communityPage=Math.max(0,Math.min(pages-1,page));renderCommunity();document.getElementById('community').scrollIntoView({behavior:'smooth',block:'start'})}
    function renderPagination(){const rows=filteredCommunityApps();const pages=Math.max(1,Math.ceil(rows.length/PAGE_SIZE));if(communityPage>=pages)communityPage=pages-1;let html=`<button class="pageBtn" ${communityPage===0?'disabled':''} data-community-page="${communityPage-1}" aria-label="${tr('Předchozí stránka','Previous page')}">‹</button>`;for(let i=0;i<pages;i++)html+=`<button class="pageBtn ${i===communityPage?'active':''}" data-community-page="${i}" ${i===communityPage?'aria-current="page"':''}>${i+1}</button>`;html+=`<button class="pageBtn" ${communityPage===pages-1?'disabled':''} data-community-page="${communityPage+1}" aria-label="${tr('Další stránka','Next page')}">›</button>`;const info=rows.length?tr(`Stránka ${communityPage+1} z ${pages} · ${rows.length} vybraných`,`Page ${communityPage+1} of ${pages} · ${rows.length} selected`):tr('Žádné výsledky','No results');for(const id of ['pagination','paginationBottom'])document.getElementById(id).innerHTML=html;for(const id of ['pageInfo','pageInfoBottom'])document.getElementById(id).textContent=info;const currentPageCards=Math.max(0,Math.min(PAGE_SIZE,rows.length-communityPage*PAGE_SIZE));const bottom=document.getElementById('paginationBottom').closest('.catalogBottom');if(bottom)bottom.style.display=currentPageCards>=4?'':'none'}
    function renderCommunity(){const filtered=filteredCommunityApps();const start=communityPage*PAGE_SIZE;const rows=filtered.slice(start,start+PAGE_SIZE);document.getElementById('communityGrid').innerHTML=rows.length?rows.map((app,i)=>cardHtml(app,start+i,true)).join(''):`<div class="emptyState">${tr('Pro tento filtr nebo hledání nebyl nalezen žádný projekt.','No projects matched this filter or search.')}</div>`;renderPagination()}
    function renderAll(){document.getElementById('ourCount').textContent=ourApps.length+' '+tr(ourApps.length===1?'aplikace':'aplikací',ourApps.length===1?'app':'apps');document.getElementById('ourGrid').innerHTML=ourApps.map((app,i)=>cardHtml(app,i,false)).join('');renderCommunityFilters();updateCommunityCount();renderCommunity();renderCommunityHealth()}

    const communityFilterHandlers={setAvailabilityFilter,setCategory,setCommunitySort};
    document.querySelector('[data-community-clear]')?.addEventListener('click',clearCommunityFilters);
    document.getElementById('sourceSearch')?.addEventListener('input',event=>setCommunitySearch(event.currentTarget.value));
    document.addEventListener('click',event=>{const target=event.target instanceof Element?event.target:null;if(!target)return;const install=target.closest('[data-install-remote]');if(install){installRemote(install.dataset.file||'',install.dataset.filename||'',install.dataset.name||'',install.dataset.statusId||'');return}const filter=target.closest('[data-community-filter]');if(filter){const handler=communityFilterHandlers[filter.dataset.communityFilter];if(handler)handler(filter.dataset.filterValue||'all');return}const pageButton=target.closest('[data-community-page]');if(pageButton&&!pageButton.disabled){const page=Number.parseInt(pageButton.dataset.communityPage||'',10);if(Number.isFinite(page))setCommunityPage(page)}});
    document.addEventListener('error',event=>{const image=event.target;if(image instanceof HTMLImageElement&&image.closest('.preview'))image.style.display='none'},true);
    document.querySelectorAll('[data-language]').forEach(btn=>btn.addEventListener('click',()=>setLanguage(btn.dataset.language)));
    document.getElementById('themeDark').addEventListener('click',()=>applyTheme('dark'));document.getElementById('themeLight').addEventListener('click',()=>applyTheme('light'));document.getElementById('layoutGrid').addEventListener('click',()=>applyLayout('grid'));document.getElementById('layoutList').addEventListener('click',()=>applyLayout('list'));
    document.getElementById('settingsBtn').addEventListener('click',e=>{e.stopPropagation();document.getElementById('settingsPanel').classList.toggle('open')});document.getElementById('settingsPanel').addEventListener('click',e=>e.stopPropagation());document.addEventListener('click',()=>document.getElementById('settingsPanel').classList.remove('open'));
    let supportReturnFocus=null;function openSupport(){const modal=document.getElementById('supportModal');supportReturnFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;modal?.classList.add('open');document.body.classList.add('modal-open');modal?.setAttribute('aria-hidden','false');requestAnimationFrame(()=>modal?.querySelector('[data-support-close]')?.focus())}function closeSupport(){const modal=document.getElementById('supportModal');const wasOpen=modal?.classList.contains('open');modal?.classList.remove('open');document.body.classList.remove('modal-open');modal?.setAttribute('aria-hidden','true');if(wasOpen&&supportReturnFocus){const target=supportReturnFocus;supportReturnFocus=null;requestAnimationFrame(()=>target.focus?.())}}document.querySelectorAll('[data-support-open]').forEach(btn=>btn.addEventListener('click',openSupport));document.querySelectorAll('[data-support-close]').forEach(btn=>btn.addEventListener('click',closeSupport));document.getElementById('supportModal')?.addEventListener('click',e=>{if(e.target.id==='supportModal')closeSupport()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeSupport()});
    document.getElementById('year').textContent=new Date().getFullYear();
    applyTheme(theme);applyLayout(layout);setLanguage(lang);
      loadCommunityStatus();

(()=>{
    const selector='.filter-tabs';
    const getScroller=target=>target instanceof Element?target.closest(selector):null;
    const canScroll=scroller=>Boolean(scroller&&scroller.scrollWidth>scroller.clientWidth+1);
    document.addEventListener('wheel',event=>{const scroller=getScroller(event.target);if(!canScroll(scroller))return;const delta=Math.abs(event.deltaX)>Math.abs(event.deltaY)?event.deltaX:event.deltaY;if(!delta)return;const max=Math.max(0,scroller.scrollWidth-scroller.clientWidth);const atStart=scroller.scrollLeft<=0;const atEnd=scroller.scrollLeft>=max-1;if((delta<0&&atStart)||(delta>0&&atEnd))return;scroller.scrollLeft+=delta;event.preventDefault()},{passive:false});
    document.addEventListener('keydown',event=>{if(event.key!=='ArrowLeft'&&event.key!=='ArrowRight')return;const scroller=getScroller(event.target);if(!canScroll(scroller))return;if(event.target instanceof HTMLInputElement||event.target instanceof HTMLTextAreaElement)return;scroller.scrollBy({left:event.key==='ArrowLeft'?-120:120,behavior:'smooth'})});
    document.addEventListener('click',event=>{const scroller=getScroller(event.target);if(!scroller)return;const item=event.target.closest('button,a,[role="option"],[role="tab"]');if(item&&scroller.contains(item))requestAnimationFrame(()=>item.scrollIntoView({block:'nearest',inline:'nearest',behavior:'smooth'}))});
    let drag=null;
    document.addEventListener('touchstart',event=>{if(event.touches.length!==1)return;const scroller=getScroller(event.target);if(!canScroll(scroller))return;const touch=event.touches[0];drag={scroller,startX:touch.clientX,startY:touch.clientY,startScrollLeft:scroller.scrollLeft,horizontal:false}},{passive:true});
    document.addEventListener('touchmove',event=>{if(!drag||event.touches.length!==1)return;const touch=event.touches[0],dx=touch.clientX-drag.startX,dy=touch.clientY-drag.startY;if(!drag.horizontal){if(Math.abs(dx)<6&&Math.abs(dy)<6)return;if(Math.abs(dy)>Math.abs(dx)){drag=null;return}drag.horizontal=true}drag.scroller.scrollLeft=drag.startScrollLeft-dx;event.preventDefault()},{passive:false});
    const clear=()=>{drag=null};document.addEventListener('touchend',clear,{passive:true});document.addEventListener('touchcancel',clear,{passive:true});
  })();

(()=>{
  const sync=()=>{
    const lang=(localStorage.getItem('siteLang')||document.documentElement.lang||'en').slice(0,2);
    document.querySelectorAll('[data-language]').forEach(btn=>btn.setAttribute('aria-checked',String(btn.dataset.language===lang)));
    const theme=document.documentElement.dataset.theme||localStorage.getItem('siteTheme')||'dark';
    document.getElementById('themeDark')?.setAttribute('aria-pressed',String(theme==='dark'));
    document.getElementById('themeLight')?.setAttribute('aria-pressed',String(theme==='light'));
    const layout=localStorage.getItem('siteLayout')||'grid';
    document.getElementById('layoutGrid')?.setAttribute('aria-pressed',String(layout==='grid'));
    document.getElementById('layoutList')?.setAttribute('aria-pressed',String(layout==='list'));
  };
  sync();
  document.addEventListener('click',e=>{if(e.target.closest('[data-language],#themeDark,#themeLight,#layoutGrid,#layoutList'))requestAnimationFrame(sync)});
})();
